import { test, expect } from '@playwright/test';

test.describe('1. Админ-панель — матрица прав и спец. действия', () => {
  test('1.12 Гость открывает /reset-password — поля нового пароля @desktop @prod-safe (#6a8ffaeb9ee5a7da68ca5bc7)', async ({ page }) => {
    // 1. Открыть `/reset-password`.
    await page.goto('/reset-password');

    // Остаётся на /reset-password; заголовок
    await expect(page).toHaveURL(/\/reset-password/);
    await expect(page.getByText(/Choose a new password|בחירת סיסמה חדשה/)).toBeVisible();
    // Поля «New password» и «Confirm password»
    await expect(page.getByText(/New password|סיסמה חדשה/).first()).toBeVisible();
    await expect(page.getByText(/Confirm password|אימות סיסמה/)).toBeVisible();
    await expect(page.getByRole('textbox')).toHaveCount(2);
    // Подсказка о требованиях
    await expect(page.getByText(/at least 8|לפחות 8 תווים/i)).toBeVisible();
    // Кнопка «Save password» (не нажимать)
    await expect(page.getByRole('button', { name: /Save password|שמירת סיסמה/ })).toBeVisible();
  });
});
